  92| // Zone memory auto-allocation function that allocates the zone size
  93| // by trying progressively smaller zone sizes until one is found that
  94| // works.
  95| 
  96| static byte *AutoAllocMemory(int *size, int default_ram, int min_ram)
  97| {
  98|     byte *zonemem;
  99| 
 100|     // Allocate the zone memory.  This loop tries progressively smaller
 101|     // zone sizes until a size is found that can be allocated.
 102|     // If we used the -mb command line parameter, only the parameter
 103|     // provided is accepted.
 104| 
 105|     zonemem = NULL;
 106| 
 107|     while (zonemem == NULL)
 108|     {
 109|         // We need a reasonable minimum amount of RAM to start.
 110| 
 111|         if (default_ram < min_ram)
 112|         {
 113|             I_Error("Unable to allocate %i MiB of RAM for zone", default_ram);
 114|         }
 115| 
 116|         // Try to allocate the zone memory.
 117| 
 118|         *size = default_ram * 1024 * 1024;
 119| 
 120|         zonemem = malloc(*size);
 121| 
 122|         // Failed to allocate?  Reduce zone size until we reach a size
 123|         // that is acceptable.
 124| 
 125|         if (zonemem == NULL)
 126|         {
 127|             default_ram -= 1;
 128|         }
 129|     }
 130| 
 131|     return zonemem;
 132| }
 133| 
 134| byte *I_ZoneBase (int *size)
 135| {
 136|     byte *zonemem;
 137|     int min_ram, default_ram;
 138|     int p;
 139| 
 140|     //!
 141|     // @arg <mb>
 142|     //
 143|     // Specify the heap size, in MiB (default 16).
 144|     //
 145| 
 146|     p = M_CheckParmWithArgs("-mb", 1);
 147| 
 148|     if (p > 0)
 149|     {
 150|         default_ram = atoi(myargv[p+1]);
 151|         min_ram = default_ram;
 152|     }
 153|     else
 154|     {
 155|         default_ram = DEFAULT_RAM;
 156|         min_ram = MIN_RAM;
 157|     }
 158| 
 159|     zonemem = AutoAllocMemory(size, default_ram, min_ram);
 160| 
 161|     printf("zone memory: %p, %x allocated for zone\n", 
 162|            zonemem, *size);
 163| 
 164|     return zonemem;
 165| }
