 247| void I_Quit (void)
 248| {
 249|     atexit_listentry_t *entry;
 250| 
 251|     // Run through all exit functions
 252|  
 253|     entry = exit_funcs; 
 254| 
 255|     while (entry != NULL)
 256|     {
 257|         entry->func();
 258|         entry = entry->next;
 259|     }
 260| 
 261| #if ORIGCODE
 262|     SDL_Quit();
 263| 
 264|     exit(0);
 265| #endif
 266| }
