 278| // Escape special characters in the given string so that they can be
 279| // safely enclosed in shell quotes.
 280| 
 281| static char *EscapeShellString(char *string)
 282| {
 283|     char *result;
 284|     char *r, *s;
 285| 
 286|     // In the worst case, every character might be escaped.
 287|     result = malloc(strlen(string) * 2 + 3);
 288|     r = result;
 289| 
 290|     // Enclosing quotes.
 291|     *r = '"';
 292|     ++r;
 293| 
 294|     for (s = string; *s != '\0'; ++s)
 295|     {
 296|         // From the bash manual:
 297|         //
 298|         //  "Enclosing characters in double quotes preserves the literal
 299|         //   value of all characters within the quotes, with the exception
 300|         //   of $, `, \, and, when history expansion is enabled, !."
