 129| // Helper function to initialize the filesystem
 130| void init_filesystem() {
 131|     // Create root directory if it doesn't exist
 132|     if (root == NULL) {
 133|         root = (FileNode*)malloc(sizeof(FileNode));
 134|         strcpy(root->name, "/");
 135|         root->type = FILE_TYPE_DIRECTORY;
 136|         root->created = root->modified = root->accessed = time(NULL);
 137|         root->data = NULL;
 138|         root->size = 0;
 139|         root->capacity = 0;
 140|         root->entries = (DirEntry*)malloc(10 * sizeof(DirEntry));
 141|         root->num_entries = 0;
 142|         root->max_entries = 10;
 143|         root->parent = root; // Root is its own parent
 144|         
 145|         // Initialize file descriptor table
 146|         for (int i = 0; i < MAX_FILE_DESCRIPTORS; i++) {
 147|             if (i < 5) {
 148|                 fd_table[i].used = 1;  // Reserve file descriptors 0-4
 149|                 fd_table[i].node = 0x12345;
 150|             } else {
 151|                 fd_table[i].used = 0;
 152|             }
 153|         }
 154|         
 155|         // Load doom.wad from the real filesystem
 156|         const char* wad_path = "doom.wad";
 157|         
 158|         // Open the WAD file from the real filesystem
 159|         int real_fd = real_syscall6(SYS_open, (long)wad_path, O_RDONLY, 0, 0, 0, 0);
 160|         if (real_fd >= 0) {
 161|             // Get the file size
 162|             off_t file_size = real_syscall6(SYS_lseek, real_fd, 0, SEEK_END, 0, 0, 0);
 163|             real_syscall6(SYS_lseek, real_fd, 0, SEEK_SET, 0, 0, 0); // Reset to beginning
 164|             
 165|             if (file_size > 0 && file_size <= MAX_FILE_SIZE) {
 166|                 // Allocate memory for the file data
 167|                 unsigned char* wad_data = (unsigned char*)malloc(file_size);
 168|                 if (wad_data != NULL) {
 169|                     // Read the file data
 170|                     ssize_t bytes_read = real_syscall6(SYS_read, real_fd, (long)wad_data, file_size, 0, 0, 0);
 171|                     
 172|                     if (bytes_read == file_size) {
 173|                         // Create a new file node for doom.wad
 174|                         FileNode* wad_node = create_node("doom.wad", FILE_TYPE_REGULAR, root);
 175|                         wad_node->data = wad_data;
 176|                         wad_node->size = file_size;
 177|                         wad_node->capacity = file_size;
 178|                         
 179|                         // Add the file to the root directory
 180|                         add_to_directory(root, "doom.wad", wad_node);
 181|                         
 182|                         printf("Loaded doom.wad (%d bytes) into in-memory filesystem\n", file_size);
 183|                     } else {
 184|                         free(wad_data);
 185|                         printf("Failed to read doom.wad: read %d of %d bytes\n", bytes_read, file_size);
 186|                     }
