 363| // SYS_read: Read from a file
 364| ssize_t sys_read(int fd, void* buf, size_t count) {
 365|     if (fd < 0 || fd >= MAX_FILE_DESCRIPTORS || !fd_table[fd].used) {
 366|         return -EBADF;
 367|     }
 368|     
 369|     FileNode* node = fd_table[fd].node;
 370|     node->accessed = time(NULL);
 371|     
 372|     if (node->type != FILE_TYPE_REGULAR) {
 373|         return -EISDIR;
 374|     }
 375|     
 376|     // Calculate how many bytes to read
 377|     size_t bytes_to_read = count;
 378|     if (fd_table[fd].position + bytes_to_read > node->size) {
 379|         bytes_to_read = node->size - fd_table[fd].position;
 380|     }
 381|     
 382|     if (bytes_to_read > 0 && node->data != NULL) {
 383|         memcpy(buf, node->data + fd_table[fd].position, bytes_to_read);
 384|         fd_table[fd].position += bytes_to_read;
 385|     }
 386|     
 387|     return bytes_to_read;
 388| }
