 390| // SYS_write: Write to a file
 391| ssize_t sys_write(int fd, const void* buf, size_t count) {
 392|     if (fd < 0 || fd >= MAX_FILE_DESCRIPTORS || !fd_table[fd].used) {
 393|         return -EBADF;
 394|     }
 395|     
 396|     FileNode* node = fd_table[fd].node;
 397|     
 398|     if (node->type != FILE_TYPE_DIRECTORY) {
 399|         // Calculate new file size
 400|         size_t new_size = fd_table[fd].position + count;
 401|         
 402|         // Check if we need to expand the file
 403|         if (new_size > node->capacity) {
 404|             size_t new_capacity = node->capacity == 0 ? 1024 : node->capacity;
 405|             while (new_capacity < new_size) {
 406|                 new_capacity *= 2;
 407|             }
 408|             
 409|             if (new_capacity > MAX_FILE_SIZE) {
 410|                 new_capacity = MAX_FILE_SIZE;
 411|                 if (new_size > MAX_FILE_SIZE) {
 412|                     count = MAX_FILE_SIZE - fd_table[fd].position;
 413|                     new_size = MAX_FILE_SIZE;
 414|                 }
 415|             }
 416|             
 417|             unsigned char* new_data = (unsigned char*)realloc(node->data, new_capacity);
 418|             if (new_data == NULL) {
 419|                 return -ENOMEM;
 420|             }
 421|             
 422|             node->data = new_data;
 423|             node->capacity = new_capacity;
 424|         }
 425|         
 426|         // Write the data
 427|         memcpy(node->data + fd_table[fd].position, buf, count);
 428|         fd_table[fd].position += count;
 429|         
 430|         if (fd_table[fd].position > node->size) {
 431|             node->size = fd_table[fd].position;
 432|         }
 433|         
 434|         node->modified = time(NULL);
 435|         
 436|         return count;
 437|     } else {
 438|         return -EISDIR; // Cannot write to a directory
 439|     }
 440| }
