#!/usr/bin/env node
'use strict';

const fs = require('fs');
const path = require('path');

const ELF32 = 1;
const PT_LOAD = 1;
const PAGE_SHIFT = 16;
const PAGE_SIZE = 1 << PAGE_SHIFT;
const PAGE_MASK = PAGE_SIZE - 1;

const O_RDONLY = 0;
const O_WRONLY = 1;
const O_RDWR = 2;
const O_CREAT = 64;
const O_EXCL = 128;
const O_TRUNC = 512;
const O_APPEND = 1024;

const ERRNO = {
  EPERM: 1,
  ENOENT: 2,
  EBADF: 9,
  EACCES: 13,
  EEXIST: 17,
  ENOTDIR: 20,
  EISDIR: 21,
  EINVAL: 22,
  ENOSPC: 28,
  ENOSYS: 38,
};

function u32(value) {
  return value >>> 0;
}

function s32(value) {
  return value | 0;
}

function sign16(value) {
  return (value << 16) >> 16;
}

function sign8(value) {
  return (value << 24) >> 24;
}

function hex(value) {
  return `0x${u32(value).toString(16).padStart(8, '0')}`;
}

class SparseMemory {
  constructor() {
    this.pages = new Map();
  }

  pageFor(address, create) {
    const pageNumber = address >>> PAGE_SHIFT;
    let page = this.pages.get(pageNumber);
    if (!page && create) {
      page = new Uint8Array(PAGE_SIZE);
      this.pages.set(pageNumber, page);
    }
    return page;
  }

  read8(address) {
    const page = this.pageFor(u32(address), false);
    return page ? page[u32(address) & PAGE_MASK] : 0;
  }

  read16(address) {
    address = u32(address);
    return (this.read8(address) |
      (this.read8(address + 1) << 8)) >>> 0;
  }

  read32(address) {
    address = u32(address);
    return (this.read8(address) |
      (this.read8(address + 1) << 8) |
      (this.read8(address + 2) << 16) |
      (this.read8(address + 3) << 24)) >>> 0;
  }

  write8(address, value) {
    address = u32(address);
    this.pageFor(address, true)[address & PAGE_MASK] = value & 0xff;
  }

  write16(address, value) {
    address = u32(address);
    this.write8(address, value);
    this.write8(address + 1, value >>> 8);
  }

  write32(address, value) {
    address = u32(address);
    value = u32(value);
    this.write8(address, value);
    this.write8(address + 1, value >>> 8);
    this.write8(address + 2, value >>> 16);
    this.write8(address + 3, value >>> 24);
  }

  readBytes(address, length) {
    address = u32(address);
    const result = Buffer.allocUnsafe(length);
    let output = 0;
    while (output < length) {
      const current = u32(address + output);
      const page = this.pageFor(current, false);
      const count = Math.min(length - output, PAGE_SIZE - (current & PAGE_MASK));
      if (page) {
        result.set(page.subarray(current & PAGE_MASK, (current & PAGE_MASK) + count), output);
      } else {
        result.fill(0, output, output + count);
      }
      output += count;
    }
    return result;
  }

  writeBytes(address, bytes) {
    address = u32(address);
    let input = 0;
    while (input < bytes.length) {
      const current = u32(address + input);
      const page = this.pageFor(current, true);
      const count = Math.min(bytes.length - input, PAGE_SIZE - (current & PAGE_MASK));
      page.set(bytes.subarray(input, input + count), current & PAGE_MASK);
      input += count;
    }
  }

  readCString(address, limit = 65536) {
    const bytes = [];
    for (let i = 0; i < limit; i++) {
      const value = this.read8(address + i);
      if (value === 0) break;
      bytes.push(value);
    }
    return Buffer.from(bytes).toString('utf8');
  }

  load(address, bytes) {
    this.writeBytes(address, bytes);
  }
}

class HostIO {
  constructor(memory, vm, outputDirectory) {
    this.memory = memory;
    this.vm = vm;
    this.nextGuestFd = 3;
    this.fds = new Map([
      [0, { realFd: 0, path: null, position: 0, standard: true }],
      [1, { realFd: 1, path: null, position: 0, standard: true }],
      [2, { realFd: 2, path: null, position: 0, standard: true }],
    ]);
    this.framePath = path.resolve('/tmp/frame.bmp');
    this.outputDirectory = outputDirectory;
    fs.mkdirSync(this.outputDirectory, { recursive: true });
    this.frameCount = 0;
  }

  hostPath(rawPath) {
    if (rawPath.startsWith('/')) return path.normalize(rawPath);
    return path.resolve(process.cwd(), rawPath);
  }

  allocGuestFd() {
    while (this.fds.has(this.nextGuestFd)) this.nextGuestFd++;
    return this.nextGuestFd++;
  }

  open(address, flags, mode) {
    const rawPath = this.memory.readCString(address);
    const hostPath = this.hostPath(rawPath);
    let nodeFlags;
    const access = flags & 3;
    if (access === O_WRONLY) nodeFlags = fs.constants.O_WRONLY;
    else if (access === O_RDWR) nodeFlags = fs.constants.O_RDWR;
    else nodeFlags = fs.constants.O_RDONLY;
    if (flags & O_CREAT) nodeFlags |= fs.constants.O_CREAT;
    if (flags & O_EXCL) nodeFlags |= fs.constants.O_EXCL;
    if (flags & O_TRUNC) nodeFlags |= fs.constants.O_TRUNC;
    if (flags & O_APPEND) nodeFlags |= fs.constants.O_APPEND;

    try {
      const realFd = fs.openSync(hostPath, nodeFlags, mode || 0o644);
      const guestFd = this.allocGuestFd();
      this.fds.set(guestFd, {
        realFd,
        path: hostPath,
        position: (flags & O_APPEND) ? fs.fstatSync(realFd).size : 0,
        flags,
        standard: false,
      });
      return guestFd;
    } catch (error) {
      return -this.errno(error);
    }
  }

  close(guestFd) {
    const entry = this.fds.get(guestFd);
    if (!entry) return -ERRNO.EBADF;
    if (entry.standard) return 0;
    try {
      fs.closeSync(entry.realFd);
      this.fds.delete(guestFd);
      if (entry.path === this.framePath) this.archiveFrame();
      return 0;
    } catch (error) {
      return -this.errno(error);
    }
  }

  read(guestFd, address, count) {
    const entry = this.fds.get(guestFd);
    if (!entry) return -ERRNO.EBADF;
    if (count < 0) return -ERRNO.EINVAL;
    if (guestFd === 0 && entry.standard) return 0;
    if (entry.standard) return -ERRNO.EBADF;
    try {
      const buffer = Buffer.allocUnsafe(count);
      const bytesRead = fs.readSync(entry.realFd, buffer, 0, count, entry.position);
      if (bytesRead > 0) {
        this.memory.writeBytes(address, buffer.subarray(0, bytesRead));
        entry.position += bytesRead;
      }
      return bytesRead;
    } catch (error) {
      return -this.errno(error);
    }
  }

  write(guestFd, address, count) {
    const entry = this.fds.get(guestFd);
    if (!entry) return -ERRNO.EBADF;
    if (count < 0) return -ERRNO.EINVAL;
    const buffer = this.memory.readBytes(address, count);
    try {
      if (entry.standard) {
        const bytesWritten = fs.writeSync(entry.realFd, buffer, 0, buffer.length);
        return bytesWritten;
      }
      const bytesWritten = fs.writeSync(entry.realFd, buffer, 0, buffer.length, entry.position);
      entry.position += bytesWritten;
      return bytesWritten;
    } catch (error) {
      return -this.errno(error);
    }
  }

  lseek(guestFd, offset, whence) {
    const entry = this.fds.get(guestFd);
    if (!entry || entry.standard) return -ERRNO.EBADF;
    try {
      let position;
      if (whence === 0) position = offset;
      else if (whence === 1) position = entry.position + offset;
      else if (whence === 2) position = fs.fstatSync(entry.realFd).size + offset;
      else return -ERRNO.EINVAL;
      if (position < 0) return -ERRNO.EINVAL;
      entry.position = position;
      return position | 0;
    } catch (error) {
      return -this.errno(error);
    }
  }

  fsync(guestFd) {
    const entry = this.fds.get(guestFd);
    if (!entry || entry.standard) return 0;
    try {
      fs.fsyncSync(entry.realFd);
      return 0;
    } catch (error) {
      return -this.errno(error);
    }
  }

  rename(oldAddress, newAddress) {
    try {
      fs.renameSync(this.hostPath(this.memory.readCString(oldAddress)), this.hostPath(this.memory.readCString(newAddress)));
      return 0;
    } catch (error) {
      return -this.errno(error);
    }
  }

  mkdir(address, mode) {
    try {
      fs.mkdirSync(this.hostPath(this.memory.readCString(address)), { mode: mode || 0o755, recursive: false });
      return 0;
    } catch (error) {
      return -this.errno(error);
    }
  }

  unlink(address) {
    try {
      fs.unlinkSync(this.hostPath(this.memory.readCString(address)));
      return 0;
    } catch (error) {
      return -this.errno(error);
    }
  }

  archiveFrame() {
    if (!fs.existsSync(this.framePath)) return;
    const filename = `frame_${String(this.frameCount).padStart(6, '0')}.bmp`;
    const destination = path.join(this.outputDirectory, filename);
    fs.copyFileSync(this.framePath, destination);
    this.frameCount++;
    process.stderr.write(`saved ${destination}\n`);
    if (this.vm.maxFrames > 0 && this.frameCount >= this.vm.maxFrames) {
      this.vm.halted = true;
    }
  }

  errno(error) {
    if (error && typeof error.errno === 'number') {
      const value = Math.abs(error.errno);
      if (value < 1000) return value;
    }
    switch (error && error.code) {
      case 'ENOENT': return ERRNO.ENOENT;
      case 'EACCES': return ERRNO.EACCES;
      case 'EEXIST': return ERRNO.EEXIST;
      case 'EBADF': return ERRNO.EBADF;
      case 'EISDIR': return ERRNO.EISDIR;
      case 'ENOTDIR': return ERRNO.ENOTDIR;
      default: return ERRNO.EINVAL;
    }
  }

  syscall(number, vm) {
    const a0 = vm.readReg(4);
    const a1 = vm.readReg(5);
    const a2 = vm.readReg(6);
    const a3 = vm.readReg(7);
    const t0 = vm.readReg(8);
    const t1 = vm.readReg(9);
    switch (number >>> 0) {
      case 0: return this.read(a0, a1, a2 >>> 0);
      case 1: return this.write(a0, a1, a2 >>> 0);
      case 2: return this.open(a0, a1, a2);
      case 3: return this.close(a0);
      case 8: return this.lseek(a0, s32(a1), a2);
      case 35: return 0;
      case 60:
        vm.halted = true;
        return 0;
      case 74: return this.fsync(a0);
      case 82: return this.rename(a0, a1);
      case 83: return this.mkdir(a0, a1);
      case 87: return this.unlink(a0);
      case 96: {
        const now = Date.now();
        if (a0) {
          vm.memory.write32(a0, Math.floor(now / 1000));
          vm.memory.write32(a0 + 4, (now % 1000) * 1000);
        }
        return 0;
      }
      case 201: {
        const seconds = Math.floor(Date.now() / 1000);
        if (a0) vm.memory.write32(a0, seconds);
        return seconds;
      }
      default:
        void a3;
        void t0;
        void t1;
        return -ERRNO.ENOSYS;
    }
  }
}

class MipsVM {
  constructor(elfPath, options = {}) {
    this.elfPath = elfPath;
